const item = $input.first().json;
const body = item.body || item;

const base64 = body.audio_base64;
const buffer = Buffer.from(base64, 'base64');

const phoneRaw = String(body.phone || '');
const phoneDigits = phoneRaw.replace(/[^0-9]/g, '');

let country = 'unknown';

if (phoneDigits.startsWith('91')) {
  country = 'india';
}
else if (phoneDigits.startsWith('977')) {
  country = 'nepal';
}
else if (phoneDigits.startsWith('58')) {
  country = 'venezuela';
}
else if (phoneDigits.startsWith('52')) {
  country = 'mexico';
}
else if (phoneDigits.startsWith('57')) {
  country = 'colombia';
}

return [{
  json: {
    phone: body.phone,
    date: body.date,
    filename: body.filename,
    country: country
  },
  binary: {
    data: {
      data: buffer.toString('base64'),
      mimeType: 'audio/wav',
      fileName: body.filename
    }
  }
}];

const driveData = $input.first().json;
const originalBinary = $('Convert Base64 to Binary2').first().binary;

return [{
  json: driveData,
  binary: originalBinary
}];

// Lee grabaciones del worker Stringee y deja pasar SOLO las que
// corresponde procesar en esta corrida. Tres filtros, en este orden:
//
//   1. YA ENVIADAS  -> el worker devuelve TODO su historial en cada
//      llamada a /recordings, sin filtro de fecha. Sin este control,
//      cada corrida reenviaba el historial completo a Telegram y
//      reintentaba subir al CRM lo ya subido.
//   2. SOLO DE HOY  -> WF10 corre para las conversaciones del día.
//   3. DURACION >= MIN_SECS -> se lee del header del WAV, no del
//      tamaño en bytes (que depende del sample rate y daría mal).
//
// La duracion queda en duration_secs, que es lo que usan los captions
// de Telegram. Antes el caption leia .duration, un campo que nunca
// existio: por eso todos los mensajes terminaban en "— s".

const MIN_SECS = 60;

// Lista de lo ya enviado, del nodo MySQL anterior.
const yaEnviadas = new Set(
  $input.all()
    .map(i => i.json && i.json.filename)
    .filter(Boolean)
);

// Fecha de hoy en UTC (el worker sella timestamp_ms en epoch UTC).
const hoy = new Date().toISOString().split('T')[0];

function wavDurationSecs(b64, sizeBytes) {
  // Header WAV canonico: byteRate en el offset 28 (uint32 LE).
  // duracion = (bytes de audio) / byteRate.
  try {
    const head = Buffer.from(b64.slice(0, 120), 'base64');
    if (head.length < 44) return null;
    if (head.toString('ascii', 0, 4) !== 'RIFF') return null;
    const byteRate = head.readUInt32LE(28);
    if (!byteRate) return null;
    const dataBytes = Math.max(0, (sizeBytes || head.length) - 44);
    return Math.round(dataBytes / byteRate);
  } catch (e) {
    return null;
  }
}

const listData = await this.helpers.httpRequest({
  method: 'GET',
  url: 'http://172.18.0.1:8091/recordings',
  json: true
});
const files = listData.recordings || [];

const results = [];
let skipEnviada = 0, skipVieja = 0, skipCorta = 0, skipError = 0;

for (const rec of files) {
  try {
    if (yaEnviadas.has(rec.filename)) { skipEnviada++; continue; }

    const fecha = new Date(rec.timestamp_ms).toISOString().split('T')[0];
    if (fecha !== hoy) { skipVieja++; continue; }

    const dlData = await this.helpers.httpRequest({
      method: 'GET',
      url: `http://172.18.0.1:8091/recordings/${rec.filename}`,
      json: true
    });
    if (!dlData.ok || !dlData.audio_base64) { skipError++; continue; }

    const secs = wavDurationSecs(dlData.audio_base64, rec.size_bytes);
    // Si el header no se pudo leer (secs === null) la grabacion NO se
    // descarta: se deja pasar y se marca para revisar. Descartar por no
    // poder medir perderia conversaciones reales en silencio.
    if (secs !== null && secs < MIN_SECS) { skipCorta++; continue; }

    const digits = String(rec.phone).replace(/[^0-9]/g, '');
    let country = 'unknown';
    if (digits.startsWith('977')) country = 'nepal';
    else if (digits.startsWith('52')) country = 'mexico';
    else if (digits.startsWith('91')) country = 'india';

    results.push({
      json: {
        phone: rec.phone,
        date: fecha,
        filename: rec.filename,
        country: country,
        size_bytes: rec.size_bytes,
        duration_secs: secs === null ? 0 : secs,
        duration_unknown: secs === null
      },
      binary: {
        data: { data: dlData.audio_base64, mimeType: 'audio/wav', fileName: rec.filename }
      }
    });
  } catch (e) {
    skipError++;
  }
}

console.log(`WF10 Stringee: ${files.length} en el worker -> ${results.length} a procesar ` +
            `| ya enviadas: ${skipEnviada} | no son de hoy: ${skipVieja} ` +
            `| < ${MIN_SECS}s: ${skipCorta} | error: ${skipError}`);

return results;

return $input.all().map((item, index) => {
  const driveData = item.json;
  const originalBinary = $('🔄 Fetch & Convert Stringee Recordings2').itemMatching(index).binary;

  return {
    json: driveData,
    binary: originalBinary
  };
});

try {
  const token = $input.item.json.accessToken;
  const lookup = $('🔍 Lookup Followup ID (Asterisk)2').item.json;
  const original = $('Convert Base64 to Binary2').item;
  return [{
    json: { ...original.json, accessToken: token, followup_id: lookup.followup_id, lead_id: lookup.lead_id },
    binary: original.binary
  }];
} catch (e) {
  console.log('Attach Audio + Token fallo: ' + e.message + ' -- se deja pasar para que Telegram no se corte');
  return { json: { _attach_error: e.message } };
}

try {
  const token = $input.item.json.accessToken;
  const lookup = $('🔍 Lookup Followup ID (Stringee)2').item.json;
  const original = $('🔄 Fetch & Convert Stringee Recordings2').item;
  return {
    json: { ...original.json, accessToken: token, followup_id: lookup.followup_id, lead_id: lookup.lead_id },
    binary: original.binary
  };
} catch (e) {
  console.log('Attach Audio + Token fallo: ' + e.message + ' -- se deja pasar para que Telegram no se corte');
  return { json: { _attach_error: e.message } };
}

// Arma un solo INSERT con todas las grabaciones de esta corrida.
// Se lee del nodo Fetch (no de $input) porque los nodos de Telegram
// reemplazan el json del item con la respuesta de su API y pierden
// filename/phone.
function esc(v) {
  if (v === null || v === undefined || v === '') return 'NULL';
  return "'" + String(v).replace(/\\/g, '\\\\').replace(/'/g, "''") + "'";
}
function num(v) { const n = Number(v); return Number.isFinite(n) ? n : 0; }

const items = $('🔄 Fetch & Convert Stringee Recordings2').all();
if (!items.length) {
  console.log('WF10: nada que registrar en el ledger');
  return [];
}

const values = items.map(it => {
  const r = it.json;
  return '(' + [esc(r.filename), esc(r.phone), esc(r.country), num(r.duration_secs)].join(',') + ')';
}).join(',\n');

// ON DUPLICATE KEY: si por una carrera dos corridas tomaran el mismo
// archivo, la segunda no explota ni crea una fila duplicada.
const sql = `INSERT INTO wf10_sent_recordings (filename, phone, country, duration_secs)
VALUES
${values}
ON DUPLICATE KEY UPDATE sent_at = sent_at;`;

console.log(`WF10: registrando ${items.length} grabacion(es) en el ledger`);
return [{ json: { sql, n: items.length } }];

